package com.mobicom.s18.domanais.joshua.beybladextournamentmanager.examples

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.mobicom.s18.domanais.joshua.beybladextournamentmanager.data.MatchRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

/**
 * Example ViewModel demonstrating how to use the generateBracket function.
 * 
 * This is a reference implementation showing:
 * 1. How to call the bracket generation function
 * 2. How to handle success/failure cases
 * 3. How to update UI state based on results
 * 
 * USAGE IN YOUR ACTUAL CODE:
 * - Call viewModel.generateBracketForTournament(tournamentId) from your Composable
 * - Observe the state flows to update your UI
 */
class BracketGenerationExampleViewModel : ViewModel() {

    private val matchRepository = MatchRepository()

    // UI State
    private val _isGenerating = MutableStateFlow(false)
    val isGenerating: StateFlow<Boolean> = _isGenerating

    private val _successMessage = MutableStateFlow<String?>(null)
    val successMessage: StateFlow<String?> = _successMessage

    private val _errorMessage = MutableStateFlow<String?>(null)
    val errorMessage: StateFlow<String?> = _errorMessage

    /**
     * Generate bracket with mock data (current implementation)
     * 
     * @param tournamentId The ID of the tournament
     * @param format The tournament format (e.g., "First to Four", "Best of 5")
     */
    fun generateBracketForTournament(
        tournamentId: String,
        format: String = "First to Four"
    ) {
        viewModelScope.launch {
            _isGenerating.value = true
            _successMessage.value = null
            _errorMessage.value = null

            try {
                val result = matchRepository.generateBracket(
                    tournamentId = tournamentId,
                    tournamentFormat = format
                )

                result.onSuccess { matchCount ->
                    _successMessage.value = "Bracket generated successfully! Created $matchCount matches."
                    println("✅ Bracket Generation Success: $matchCount matches created for tournament $tournamentId")
                }.onFailure { exception ->
                    _errorMessage.value = "Failed to generate bracket: ${exception.message}"
                    println("❌ Bracket Generation Failed: ${exception.message}")
                }
            } catch (e: Exception) {
                _errorMessage.value = "Unexpected error: ${e.message}"
                println("❌ Unexpected Error: ${e.message}")
            } finally {
                _isGenerating.value = false
            }
        }
    }

    /**
     * FUTURE: Generate bracket with real participants
     * Use this when the Join Tournament feature is implemented
     * 
     * @param tournamentId The ID of the tournament
     * @param participants List of (userId, userName) pairs
     * @param format The tournament format
     */
    fun generateBracketWithRealParticipants(
        tournamentId: String,
        participants: List<Pair<String, String>>,
        format: String = "First to Four"
    ) {
        viewModelScope.launch {
            _isGenerating.value = true
            _successMessage.value = null
            _errorMessage.value = null

            try {
                // Validate participants
                if (participants.size < 2) {
                    _errorMessage.value = "At least 2 participants required to generate bracket"
                    _isGenerating.value = false
                    return@launch
                }

                val result = matchRepository.generateBracketWithParticipants(
                    tournamentId = tournamentId,
                    participants = participants,
                    tournamentFormat = format
                )

                result.onSuccess { matchCount ->
                    _successMessage.value = "Bracket generated successfully! Created $matchCount matches with ${participants.size} players."
                    println("✅ Bracket Generation Success: $matchCount matches created")
                }.onFailure { exception ->
                    _errorMessage.value = "Failed to generate bracket: ${exception.message}"
                    println("❌ Bracket Generation Failed: ${exception.message}")
                }
            } catch (e: Exception) {
                _errorMessage.value = "Unexpected error: ${e.message}"
                println("❌ Unexpected Error: ${e.message}")
            } finally {
                _isGenerating.value = false
            }
        }
    }

    /**
     * Clear messages after they've been displayed
     */
    fun clearMessages() {
        _successMessage.value = null
        _errorMessage.value = null
    }
}

/**
 * Example usage in a Composable screen:
 * 
 * @Composable
 * fun TournamentDetailsScreen(
 *     tournamentId: String,
 *     viewModel: BracketGenerationExampleViewModel = viewModel()
 * ) {
 *     val isGenerating by viewModel.isGenerating.collectAsState()
 *     val successMessage by viewModel.successMessage.collectAsState()
 *     val errorMessage by viewModel.errorMessage.collectAsState()
 * 
 *     Column(modifier = Modifier.padding(16.dp)) {
 *         // Generate Bracket Button
 *         Button(
 *             onClick = { 
 *                 viewModel.generateBracketForTournament(
 *                     tournamentId = tournamentId,
 *                     format = "First to Four"
 *                 )
 *             },
 *             enabled = !isGenerating
 *         ) {
 *             if (isGenerating) {
 *                 CircularProgressIndicator(modifier = Modifier.size(20.dp))
 *             } else {
 *                 Text("Generate Bracket")
 *             }
 *         }
 * 
 *         // Success Message
 *         successMessage?.let { message ->
 *             Text(
 *                 text = message,
 *                 color = Color.Green,
 *                 modifier = Modifier.padding(top = 8.dp)
 *             )
 *             LaunchedEffect(message) {
 *                 delay(3000)
 *                 viewModel.clearMessages()
 *             }
 *         }
 * 
 *         // Error Message
 *         errorMessage?.let { message ->
 *             Text(
 *                 text = message,
 *                 color = Color.Red,
 *                 modifier = Modifier.padding(top = 8.dp)
 *             )
 *         }
 *     }
 * }
 */
